// Frame interpolation's shader blob accessor (ADR 0091), in place of the SDK's
// sdk/src/backends/shared/blob_accessors/ffx_frameinterpolation_shaderblobs.cpp, which
// includes headers generated by the SDK's shader compiler: the reflection and the
// permutation table in permutations_frameinterpolation.inc, the SPIR-V from Rust
// (src/blobs.rs), both from examples/ffx_shaders.rs.

#include "ffx_engine.h"

#include <FidelityFX/host/ffx_util.h>
#include "ffx_frameinterpolation_shaderblobs.h"
#include "frameinterpolation/ffx_frameinterpolation_private.h"

#include <cstring>

namespace {

#include "permutations_frameinterpolation.inc"

}  // namespace

FfxErrorCode frameInterpolationGetPermutationBlobByIndex(FfxFrameInterpolationPass passId, FfxBindStage, uint32_t permutationOptions,
                                                         FfxShaderBlob* outBlob)
{
    // The generator's shaders follow `FfxFrameInterpolationPass`. The SDK's accessor never
    // loads a 16-bit variant.
    if (uint32_t(passId) >= uint32_t(FFX_FRAMEINTERPOLATION_PASS_COUNT))
    {
        std::memset(outBlob, 0, sizeof(FfxShaderBlob));
        return FFX_ERROR_INVALID_ARGUMENT;
    }
    // The option bits below FORCE_WAVE64: the defines of the permutation.
    const uint32_t options = permutationOptions & (FRAMEINTERPOLATION_SHADER_PERMUTATION_FORCE_WAVE64 - 1);
    return engineFfxBlob(ENGINE_FFX_FRAME_INTERPOLATION, g_permutations, sizeof(g_permutations) / sizeof(g_permutations[0]),
                         g_reflection, MODULE_COUNT, uint32_t(passId), 0, options, outBlob);
}

FfxErrorCode frameInterpolationIsWave64(uint32_t permutationOptions, bool& isWave64)
{
    // The same module either way on Vulkan: the backend requests the subgroup size.
    isWave64 = FFX_CONTAINS_FLAG(permutationOptions, FRAMEINTERPOLATION_SHADER_PERMUTATION_FORCE_WAVE64);
    return FFX_OK;
}
